<?php
namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class StoreTrainingSessionRequest extends FormRequest { public function authorize(){return$this->user()?->can('capacitaciones.sesiones.crear')??false;} public function rules(){return['title'=>'required|string|max:255','description'=>'nullable|string|max:4000','training_topic_id'=>'nullable|exists:training_topics,id','training_type'=>['required',Rule::in(array_keys(config('training.training_types')))],'scheduled_start_at'=>'required|date','scheduled_end_at'=>'required|date|after:scheduled_start_at','planned_duration_minutes'=>'required|integer|min:1|max:10080','modality'=>['required',Rule::in(array_keys(config('training.modalities')))],'location'=>'nullable|string|max:255','virtual_link'=>'nullable|url|max:2000','instructor_type'=>'required|in:internal,external,arl,provider,other','instructor_employee_id'=>'nullable|required_if:instructor_type,internal|exists:empleados,id','external_instructor_id'=>'nullable|required_unless:instructor_type,internal|exists:training_instructors,id','audience_type'=>['required',Rule::in(array_keys(config('training.population_types')))],'audience_description'=>'nullable|string|max:2000','specific_employee_ids'=>'nullable|array','specific_employee_ids.*'=>'integer|exists:empleados,id','requires_attendance'=>'required|boolean','requires_signature'=>'required|boolean','requires_material'=>'required|boolean','requires_execution_report'=>'required|boolean','extraordinary_reason'=>'nullable|string|min:10|max:3000','extraordinary_origin'=>'nullable|string|max:50','induction_scope'=>'nullable|in:general,job_specific','reinduction_cause'=>'nullable|in:periodic,job_change,process_change,equipment_change,risk_change,incident,regulatory_change,other'];} }
